mapper.update:
UPDATE place_availability
SET status = 'RESERVED'
WHERE place_id = #{placeId}
AND status = 'OPEN'
AND start_at >= #{startAt}
AND end_at <= #{endAt}

UPDATE place_availability
SET status = #{status}
WHERE id = #{slotId}
AND status <> 'RESERVED'

mapper.select:
SELECT id
FROM place_availability
WHERE place_id = #{placeId}
AND start_at >= #{startAt}
AND end_at <= #{endAt}
ORDER BY start_at

SELECT
id AS slotId,
start_at AS startAt,
end_at AS endAt,
status AS status
FROM place_availability
WHERE place_id = #{placeId}
AND start_at >= #{fromAt}
AND start_at < #{toAt}
ORDER BY start_at

SELECT COUNT(*)
FROM place_availability
WHERE place_id = #{placeId}
AND status = 'OPEN'
AND start_at >= #{startAt}
AND end_at <= #{endAt}

SELECT MAX(end_at)
FROM place_availability
WHERE place_id = #{placeId}
